"""A product-backed enquiry workspace, without invented pricing or accounts."""
from pathlib import Path
from html import escape as e
import json

ROOT = Path(__file__).resolve().parents[1]

def records():
    products = json.loads((ROOT / "data/editorial-products.json").read_text(encoding="utf-8"))
    for p in products:
        p["family"] = "sarkit" if p["source_page"] < 22 else ("aplik" if p["source_page"] < 25 else "lambader")
        p["name"] = {"sarkit": "Artline sarkıt", "aplik": "Artline aplik", "lambader": "Artline lambader"}[p["family"]]
    return products

def b2b_page(icon, breadcrumb):
    products = records()
    cards = []
    for p in products:
        measure = lambda value: e(value) + " cm" if value else "Teyit gerekli"
        warning = '<span class="b2b-warning">Kod / ölçü teyidi gerekli</span>' if "*" in p["code"] or p["width"] is None or p["height"] is None else ""
        cards.append(f'''<article class="b2b-product" data-b2b-card data-family="{p['family']}" data-search="{e(p['code']+' '+p['name'])}">
          <a href="/urunler/#sayfa-{p['page']}" aria-label="{e(p['code'])} katalog sayfası"><img src="{p['web_image']}" width="{p['image_width']}" height="{p['image_height']}" alt="{e(p['code']+' '+p['name'])}" loading="lazy"></a>
          <div class="b2b-product-info"><small>{p['name']}</small><h3>{e(p['code'])} <span>{p['power']} W</span></h3><p>G: {measure(p['width'])}<br>Y: {measure(p['height'])}</p>{warning}<button class="button outline" type="button" data-b2b-add="{e(p['code'])}">Listeye ekle +</button></div></article>''')
    return f'''<div class="container">{breadcrumb([('B2C teklif',None)])}</div>
    <section class="b2b-intro"><div class="container b2b-intro-grid"><div><span class="eyebrow">B2C · BİREYSEL ALIŞVERİŞ</span><h1>Evinizin ışığını seçin.<br><em>Listenizi birlikte tamamlayalım.</em></h1><p>Beğendiğiniz ürünleri seçin, ihtiyacınız olan adetleri ekleyin. Eviniz veya yaşam alanınız için güncel fiyatı, renk seçeneklerini ve teslim bilgisini WhatsApp üzerinden öğrenin.</p><div class="b2b-intro-actions"><a class="button yellow" href="#b2b-urunler">Ürün seçin {icon('arrow')}</a><a class="text-link" href="#hizli-giris">Kodla hızlı giriş {icon('up')}</a></div></div><aside class="b2b-how"><span>NASIL İLERLER?</span><ol><li><b>01</b><div>Listenizi oluşturun<small>Ürün seçin veya katalog kodunu yazın.</small></div></li><li><b>02</b><div>İhtiyacınızı anlatın<small>Odanızı, ışık rengini ve tercihlerinizi belirtin.</small></div></li><li><b>03</b><div>Teklif isteyin<small>Özeti WhatsApp'ta mağazamıza gönderin.</small></div></li></ol><p>Fiyat ve bulunabilirlik görüşmede netleşir. Bu ekran kesin sipariş veya ödeme oluşturmaz.</p></aside></div></section>
    <div class="container b2b-workspace" data-b2b-root>
      <section class="b2b-browser" id="b2b-urunler"><div class="section-head"><div><span class="eyebrow">ÜRÜN SEÇİMİ</span><h2>Listenize ekleyin.</h2></div><span class="b2b-count" data-b2b-count role="status">52 ürün</span></div>
      <p class="b2b-help">Artline ürünlerini buradan seçebilirsiniz. Katalogdaki diğer modeller için aşağıdaki kod girişini kullanın. <a href="/urunler/">Kataloğu açın ↗</a></p>
      <div class="b2b-toolbar"><label>Ürün ara<input type="search" data-b2b-search placeholder="Kod veya ürün adı" maxlength="80"></label><label>Ürün grubu<select data-b2b-family><option value="">Tümü</option><option value="sarkit">Sarkıt</option><option value="aplik">Aplik</option><option value="lambader">Lambader</option></select></label><a href="#talep-listesi" class="b2b-list-jump">Listem <span data-b2b-badge>0</span> ↓</a></div>
      <div class="b2b-products">{''.join(cards)}</div><button type="button" class="button outline b2b-more" data-b2b-more hidden>Daha fazla ürün göster</button><p data-b2b-empty-search hidden>Bu aramada ürün bulunamadı. Kodu aşağıdaki hızlı giriş alanından ekleyebilirsiniz.</p>
      <section class="b2b-quick" id="hizli-giris"><span class="eyebrow">HIZLI GİRİŞ</span><h2>Kodlar elinizde mi?</h2><p>Her satıra bir ürün kodu ve adet yazın. Katalogda bulunan diğer ürünleri de bu alandan talebinize ekleyebilirsiniz.</p><form data-b2b-bulk><label for="bulk-lines">Ürün kodu ; adet</label><textarea id="bulk-lines" rows="4" maxlength="4000" placeholder="AS5002; 6&#10;AS5206; 12"></textarea><p class="b2b-help">En fazla 50 kalem. Her kalemde 1–9999 adet. Tanınmayan kodlar teyit notuyla eklenir.</p><button type="submit" class="button outline">Satırları listeye ekle</button></form></section>
      </section>
      <aside class="b2b-summary" id="talep-listesi" aria-labelledby="b2b-list-title"><div class="b2b-summary-heading"><span class="eyebrow">TEKLİF TASLAĞINIZ</span><h2 id="b2b-list-title">Talep listesi <span data-b2b-badge>0</span></h2><p data-b2b-total>Henüz ürün eklenmedi.</p></div>
      <div class="b2b-empty" data-b2b-empty>Ürün seçerek başlayın.<br><small>Seçimleriniz bu cihazda 7 gün saklanır.</small></div><ul class="b2b-lines" data-b2b-lines></ul>
      <div class="b2b-list-tools"><button type="button" data-b2b-clear disabled>Listeyi temizle</button><button type="button" data-b2b-undo hidden>Geri al</button></div>
      <form data-b2b-request><div class="b2b-fields"><label>Adınız / liste adı <span>(isteğe bağlı)</span><input name="company" maxlength="120" autocomplete="off" placeholder="Örn. Ayşe / salon aydınlatması"></label><label>Teslimat şehri <span>(isteğe bağlı)</span><input name="city" maxlength="60" placeholder="Örn. İstanbul"></label><label>Kullanım alanı<select name="sector"><option value="">Seçin</option><option>Salon / oturma odası</option><option>Yemek alanı / mutfak</option><option>Yatak odası</option><option>Antre / koridor</option><option>Ev / diğer alanlar</option><option>Ofis</option><option>Mağaza / vitrin</option><option>Otel / restoran / kafe</option><option>Peyzaj / cephe</option><option>Depo / teknik alan</option><option>Diğer</option></select></label><label>Tercihleriniz ve teslim ihtiyacınız<textarea name="note" maxlength="700" rows="3" placeholder="Işık rengi, gövde rengi, ölçü veya teslim zamanı…"></textarea></label></div>
      <details class="b2b-preview"><summary>Talep özetini görüntüle</summary><textarea data-b2b-preview readonly rows="8" aria-label="Talep özeti"></textarea></details><button class="button yellow b2b-send" type="submit" data-b2b-send disabled>WhatsApp’ta teklifi iste {icon('up')}</button>
      <div class="b2b-export"><button type="button" data-b2b-copy disabled>Özeti kopyala</button><button type="button" data-b2b-csv disabled>Excel için indir</button><button type="button" data-b2b-print disabled>Yazdır / PDF</button></div>
      <p class="b2b-long" data-b2b-long hidden>Listeniz tek bağlantı için uzun. Özeti kopyalayıp <a href="https://wa.me/905456105009" target="_blank" rel="noopener noreferrer">WhatsApp sohbetine</a> yapıştırın.</p>
      <p class="b2b-help">Adınız ve diğer form bilgileri kalıcı saklanmaz. Mesajı WhatsApp içinde siz gönderirsiniz. <a href="/gizlilik/">Veri kullanımı</a></p></form><p class="b2b-status" data-b2b-status role="status" aria-live="polite"></p></aside></div>
    <noscript><div class="container"><p>Liste oluşturmak için JavaScript gereklidir. <a href="/urunler/">PDF kataloğu açın</a> veya <a href="tel:+905456105009">0545 610 50 09</a> numarasından ürün kodlarıyla bilgi alın.</p></div></noscript>
    <section class="b2b-faq"><div class="container"><span class="eyebrow">TALEPTEN SİPARİŞE</span><h2>Bir sonraki adım net olsun.</h2><div class="b2b-faq-grid"><article><h3>Fiyatları nasıl öğrenirim?</h3><p>Ürün, adet ve seçeneklerinize göre güncel fiyat bilgisi mağazamızla görüşmede netleşir. Bu sayfadaki liste fiyat veya stok garantisi içermez.</p></article><article><h3>Liste sipariş sayılır mı?</h3><p>Liste bir teklif talebidir. Ürün seçeneği, tutar, bulunabilirlik ve teslim koşulları karşılıklı netleştiğinde sipariş sürecine geçilir.</p></article><article><h3>Teknik bilgileri nasıl teyit ederim?</h3><p>Katalog sayfasını ve ürün kodunu belirtin. Ölçü, ışık rengi, sürücü, koruma sınıfı ve montaj uygunluğunu satın almadan önce teyit edin.</p></article></div></div></section>
    <script type="application/json" id="b2b-records">{json.dumps(products,ensure_ascii=False).replace('</','<\\/')}</script>'''

def solutions_page(icon, breadcrumb):
    sectors = [
      ("01","Konut & yaşam alanları","Gündelik ışık, kişisel atmosfer.","Dekoratif sarkıt, aplik ve lambader seçeneklerini birlikte değerlendirin. Genel ışık ile okuma veya yemek alanı gibi belirli ihtiyaçları ayrı düşünün.","Tavan yüksekliği · oda ölçüsü · kullanım amacı · tercih edilen gövde rengi","dekoratif","artline-sarkit"),
      ("02","Ofis & çalışma alanları","Mekânı takip eden çizgiler.","Lineer ve spot gruplarında montaj şekli, masa yerleşimi ve ışığın dağılımı seçimi belirler. Parlama ve ekran yansımalarını proje değerlendirmesine dahil edin.","Yerleşim planı · tavan tipi · çalışma alanı · armatür adedi","mimari","lineer-siva-alti"),
      ("03","Mağaza & vitrin","Ürünü doğru ışıkta gösterin.","Vitrin, raf ve genel alanın aydınlatma ihtiyacı farklı olabilir. Vurgulu ışık için spot; kesintisiz çizgiler için lineer grupları inceleyin.","Vitrin ölçüsü · sergilenen ürün · montaj mesafesi · ışık rengi","ic","spot"),
      ("04","Otel, restoran & kafe","Birbiriyle uyumlu mekânlar.","Giriş, masa, koridor ve dinlenme alanları için seçimleri aynı listede toplayın. Dekoratif ürünlerin boyutlarını mobilya ve dolaşım alanıyla birlikte değerlendirin.","Alan listesi · masa yerleşimi · dekorasyon tonu · ürün adetleri","dekoratif","artline-aplik"),
      ("05","Peyzaj & cephe","Dış mekânın gece görünümü.","Bahçe, zemin ve wallwasher ürünlerini kullanım yerine göre karşılaştırın. Su, toz ve dış ortam koşulları için ürünün uygunluğunu ayrıca teyit edin.","Montaj yeri · dış ortam koşulları · yüzey ölçüsü · kablo altyapısı","dis","bahce"),
      ("06","Depo & teknik alanlar","İşlevi belirleyen detaylar.","Yüksek tavan, projektör ve etanj gruplarında montaj yüksekliği, ortam ve bakım erişimi önemlidir. Nihai ürün ve elektrik uygulaması uzman değerlendirmesi gerektirir.","Tavan yüksekliği · alan ölçüsü · ortam koşulları · kullanım süresi","dis","kanopi")]
    catalog = json.loads((ROOT/"data/catalog.json").read_text(encoding="utf-8"))
    cards=[]
    for n,title,tagline,desc,info,family,slug in sectors:
        s=next(s for s in catalog["sections"] if s["id"]==slug)
        cards.append(f'''<article class="solution-card" id="cozum-{n}"><div class="solution-visual"><img src="{s['image']}" width="{s['width']}" height="{s['height']}" alt="{e(title)} için katalogdan aydınlatma örneği" loading="lazy"><span>{n}</span></div><div><span class="eyebrow">{e(title)}</span><h2>{tagline}</h2><p>{desc}</p><div class="solution-check"><b>Talebinize ekleyin</b><p>{info}</p></div><div class="solution-links"><a class="text-link" href="/urunler/?grup={family}#koleksiyonlar">Koleksiyona bakın {icon('arrow')}</a><a class="text-link" href="/b2c/">Talep oluşturun {icon('up')}</a></div></div></article>''')
    return f'''<div class="container">{breadcrumb([('Proje çözümleri',None)])}</div><section class="solutions-intro container"><span class="eyebrow">MEKÂNA GÖRE SEÇİM</span><h1>Mekânı anlayın.<br><em>Işığı birlikte seçelim.</em></h1><p>Bir evin, mağazanın veya iş yerinin ihtiyacı aynı değildir. Ürün gruplarını kullanım alanınızla eşleştirin; proje listenizi kod ve adetlerle hazırlayın.</p><a href="/b2c/" class="button yellow">Proje listemi oluştur {icon('arrow')}</a></section><section class="container solution-list">{''.join(cards)}</section><section class="solution-close"><div class="container"><span class="eyebrow">PROJENİZİ PAYLAŞIN</span><h2>Doğru bilgiyle daha net bir talep.</h2><p>Ölçü veya planınız varsa WhatsApp sohbetine ekleyin. Ürün seçeneklerini, fiyatı ve teslim koşullarını birlikte netleştirelim.</p><a href="/b2c/" class="button yellow">B2C teklif sayfasına geçin {icon('up')}</a><p class="b2b-help">Görseller katalogdan ürün ve kullanım örnekleridir. Tamamlanmış proje referansı değildir.</p></div></section>'''
